create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz default now());
create table if not exists public.churches(id uuid primary key default gen_random_uuid(), name text not null, created_by uuid not null references auth.users(id), created_at timestamptz default now());
create table if not exists public.church_members(church_id uuid references public.churches(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text not null default 'member' check(role in ('admin','editor','member')), joined_at timestamptz default now(), primary key(church_id,user_id));
create table if not exists public.songs(id uuid primary key default gen_random_uuid(), title text not null, artist text, source_url text, created_by uuid not null references auth.users(id), church_id uuid references public.churches(id) on delete cascade, created_at timestamptz default now());
create table if not exists public.arrangements(id uuid primary key default gen_random_uuid(), song_id uuid not null references public.songs(id) on delete cascade, owner_id uuid not null references auth.users(id), church_id uuid references public.churches(id) on delete cascade, scope text not null check(scope in ('private','church')), original_key text, tempo_bpm numeric, time_signature text, lyrics_and_chords text, analysis_status text not null default 'draft' check(analysis_status in ('draft','ai_estimated','needs_review','verified')), version integer not null default 1, created_at timestamptz default now(), updated_at timestamptz default now(), constraint arrangement_scope_consistency check((scope='private' and church_id is null) or (scope='church' and church_id is not null)));
create table if not exists public.chord_events(id uuid primary key default gen_random_uuid(), arrangement_id uuid not null references public.arrangements(id) on delete cascade, start_seconds numeric not null check(start_seconds>=0), end_seconds numeric not null check(end_seconds>start_seconds), chord_label text not null, confidence numeric check(confidence between 0 and 1), reviewer_status text not null default 'unreviewed' check(reviewer_status in ('unreviewed','accepted','corrected','rejected')));
create index if not exists church_members_user_idx on public.church_members(user_id);
create index if not exists songs_church_idx on public.songs(church_id);
create index if not exists arrangements_owner_idx on public.arrangements(owner_id);
create index if not exists arrangements_church_idx on public.arrangements(church_id);
create index if not exists chord_events_timeline_idx on public.chord_events(arrangement_id,start_seconds);
alter table public.profiles enable row level security;
alter table public.churches enable row level security;
alter table public.church_members enable row level security;
alter table public.songs enable row level security;
alter table public.arrangements enable row level security;
alter table public.chord_events enable row level security;
create policy "profile_read_self" on public.profiles for select to authenticated using(id=auth.uid());
create policy "profile_insert_self" on public.profiles for insert to authenticated with check(id=auth.uid());
create policy "profile_update_self" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "members_read_same_church" on public.church_members for select to authenticated using(exists(select 1 from public.church_members mine where mine.church_id=church_members.church_id and mine.user_id=auth.uid()));
create policy "church_read_members" on public.churches for select to authenticated using(exists(select 1 from public.church_members m where m.church_id=churches.id and m.user_id=auth.uid()));
create policy "songs_read_owner_or_member" on public.songs for select to authenticated using(created_by=auth.uid() or (church_id is not null and exists(select 1 from public.church_members m where m.church_id=songs.church_id and m.user_id=auth.uid())));
create policy "songs_insert_owner" on public.songs for insert to authenticated with check(created_by=auth.uid() and (church_id is null or exists(select 1 from public.church_members m where m.church_id=songs.church_id and m.user_id=auth.uid() and m.role in ('admin','editor'))));
create policy "arrangements_read_owner_or_member" on public.arrangements for select to authenticated using((scope='private' and owner_id=auth.uid()) or (scope='church' and exists(select 1 from public.church_members m where m.church_id=arrangements.church_id and m.user_id=auth.uid())));
create policy "arrangements_insert_owner_or_editor" on public.arrangements for insert to authenticated with check(owner_id=auth.uid() and ((scope='private' and church_id is null) or (scope='church' and exists(select 1 from public.church_members m where m.church_id=arrangements.church_id and m.user_id=auth.uid() and m.role in ('admin','editor')))));
create policy "arrangements_update_owner_or_editor" on public.arrangements for update to authenticated using((scope='private' and owner_id=auth.uid()) or (scope='church' and exists(select 1 from public.church_members m where m.church_id=arrangements.church_id and m.user_id=auth.uid() and m.role in ('admin','editor')))) with check((scope='private' and owner_id=auth.uid() and church_id is null) or (scope='church' and exists(select 1 from public.church_members m where m.church_id=arrangements.church_id and m.user_id=auth.uid() and m.role in ('admin','editor'))));
create policy "chords_read_via_arrangement" on public.chord_events for select to authenticated using(exists(select 1 from public.arrangements a where a.id=chord_events.arrangement_id and ((a.scope='private' and a.owner_id=auth.uid()) or (a.scope='church' and exists(select 1 from public.church_members m where m.church_id=a.church_id and m.user_id=auth.uid())))));
create policy "chords_insert_owner_or_editor" on public.chord_events for insert to authenticated with check(exists(select 1 from public.arrangements a where a.id=chord_events.arrangement_id and ((a.scope='private' and a.owner_id=auth.uid()) or (a.scope='church' and exists(select 1 from public.church_members m where m.church_id=a.church_id and m.user_id=auth.uid() and m.role in ('admin','editor'))))));
create policy "chords_update_owner_or_editor" on public.chord_events for update to authenticated using(exists(select 1 from public.arrangements a where a.id=chord_events.arrangement_id and ((a.scope='private' and a.owner_id=auth.uid()) or (a.scope='church' and exists(select 1 from public.church_members m where m.church_id=a.church_id and m.user_id=auth.uid() and m.role in ('admin','editor')))))) with check(exists(select 1 from public.arrangements a where a.id=chord_events.arrangement_id and ((a.scope='private' and a.owner_id=auth.uid()) or (a.scope='church' and exists(select 1 from public.church_members m where m.church_id=a.church_id and m.user_id=auth.uid() and m.role in ('admin','editor'))))));
-- Church creation and invitations must be handled by a trusted admin workflow, not by self-assignment.
